def solve(I):
    H,W=len(I),len(I[0])
    cells=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=0 and I[r][c]!=5]
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    # anchor: 5 inside pattern bbox, else unique-colored cell
    mks=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if I[r][c]==5]
    uniq=None
    cnt={}
    for _,_,v in cells: cnt[v]=cnt.get(v,0)+1
    for v,n in cnt.items():
        if n==1 and v!=5: uniq=v
    if mks: anchor=mks[0]
    else:
        for p in cells:
            if p[2]==uniq: anchor=p
    strays=[(r,c) for r in range(H) for c in range(W) if I[r][c]==5]
    # strays that are INSIDE the pattern bbox are NOT destinations (they stay)
    strays=[s for s in strays if not(r0<=s[0]<=r1 and c0<=s[1]<=c1)]
    O=[r[:] for r in I]
    for sr,sc in strays:
        tr,tc=sr-anchor[0],sc-anchor[1]
        for pr,pc,v in cells:
            rr,cc=pr+tr,pc+tc
            if 0<=rr<H and 0<=cc<W: O[rr][cc]=v
        O[sr][sc]=0
    return O

